const product = {
  name: '모자',
  price: 19000,
  stock: 7,
};

const card = { name: product.name, price: product.price };

function getCard() {
  return card;
}

function summarize(product) {
  return {
    name: product.name,
    price: product.price,
    hasStock: product.stock > 0,
  };
}
